package client

import (
	"github.com/cloudwego/kitex/internal/client"
	"github.com/cloudwego/kitex/pkg/utils"
)

// UnaryOption is an alias for options applicable to unary (request-response) calls
type UnaryOption = Option

// StreamOption is an alias for options applicable to streaming calls
type StreamOption = Option

// TTHeaderOption is an alias for options applicable to TTHeader protocol
type TTHeaderOption = Option

// TailOption represents an option that should be applied last in the option processing chain
// Useful for options that need to inspect or override previously set configurations
type TailOption struct {
	Option
}

// NewTailOption creates a new TailOption that wraps a regular Option
// TailOptions are processed after all regular options, allowing them to
	// inspect and potentially override configurations
func NewTailOption(opt Option) TailOption {
	return TailOption{Option: opt}
}

// AsTailOption converts a standard Option into a TailOption
func AsTailOption(opt Option) TailOption {
	return TailOption{Option: opt}
}

// WithRetryTail creates a retry configuration that is applied after other options
// This allows retry logic to see the final configuration state
func WithRetryTail(rc *client.RetryConfig) TailOption {
	return NewTailOption(Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push("WithRetryTail")
		o.RetryConfig = rc
	}})
}

// WithFallbackTail creates a fallback configuration that is applied after other options
// This allows fallback logic to see the final configuration state
func WithFallbackTail(fb interface{}) TailOption {
	return NewTailOption(Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push("WithFallbackTail")
		// Store fallback config in options
		// Implementation depends on internal client.Options structure
	}})
}

// processTailOptions extracts and returns tail options from a slice of options
// It also returns the remaining non-tail options
func processTailOptions(opts []Option) (regular []Option, tail []TailOption) {
	for _, opt := range opts {
		if to, ok := interface{}(opt).(TailOption); ok {
			tail = append(tail, to)
		} else {
			regular = append(regular, opt)
		}
	}
	return regular, tail
}

// applyTailOptions applies tail options after regular options have been processed
func applyTailOptions(o *client.Options, di *utils.Slice, tailOpts []TailOption) {
	for _, to := range tailOpts {
		to.Option.F(o, di)
	}
}
