	"github.com/cloudwego/kitex/transport"
)

// Option is the only way to config client.
type Option = client.Option

// Options is used to initialize a client.
type Options = client.Options

// A Suite is a collection of Options. It is useful to assemble multiple associated
// Options as a single one to keep the order or presence in a desired manner.
type Suite interface {
	Options() []Option
}

// TailOption wraps an Option to be applied after all regular options.
// This is useful for options that need to inspect or override the final configuration.
func TailOption(opt Option) Option {
	// Mark this option as a tail option by wrapping it in a special struct
	// The actual implementation needs to be coordinated with option processing logic
	return Option{F: func(o *client.Options, di *utils.Slice) {
		// Store tail options separately for deferred application
		if o.TailOptions == nil {
			o.TailOptions = []client.Option{}
		}
		o.TailOptions = append(o.TailOptions, opt)
		di.Push("TailOption(deferred)")
	}}
}
